 LogFundTransfer(msg.sender, msg.value, true);
 } else {
 throw;
 }
 }else{
 if(tokenReward.transfer(msg.sender, (msg.value*price)/price)) {
 LogFundTransfer(msg.sender, msg.value, true);
 } else {
 throw;
 }
 }
 amountRaised = safeAdd(amountRaised, msg.value);
 balanceOf[msg.sender] = safeAdd(balanceOf[msg.sender], msg.value);
 }

